import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.DB31oXgM.js";const p=JSON.parse('{"title":"ADR-007: Server-Authoritative State and Validation","description":"","frontmatter":{},"headers":[],"relativePath":"ADR_007_server_authority.md","filePath":"ADR_007_server_authority.md"}'),o={name:"ADR_007_server_authority.md"};function n(s,e,l,c,d,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-007-server-authoritative-state-and-validation" tabindex="-1">ADR-007: Server-Authoritative State and Validation <a class="header-anchor" href="#adr-007-server-authoritative-state-and-validation" aria-label="Permalink to &quot;ADR-007: Server-Authoritative State and Validation&quot;">​</a></h1><p><strong>Date:</strong> 2026-10-11<br><strong>Status:</strong> ACCEPTED<br><strong>Context:</strong> D1, D4 — Auth/authz integration, server authority validation<br><strong>Decision:</strong> Server is the sole authority on game state; clients submit inputs and receive state corrections</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Clients have predicted state (optimistic); the server has authoritative state. Conflicts arise:</p><ol><li>Client sends input with seq=42; server accepted seq=41 → out-of-order detection needed</li><li>Server rolls back to tick 10; client was at tick 15 → clients must resync</li><li>ML model suggests Player A is cheating; server must validate before accepting the score</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Three-tier validation model:</p><ol><li><strong>Handshake (Auth/authz):</strong> Client identity + session token verified before any game input</li><li><strong>Input Validation (D4):</strong> Each InputFrame checked for: <ul><li>Valid sequence number (&gt; last_acked)</li><li>Valid replay state (not a repeat of already-executed frame)</li><li>Bounds checking (input values in legal range, e.g., 0–360 for angle)</li></ul></li><li><strong>State Authority:</strong> Only server state after <code>Replayed from [X]</code> tick is considered canonical; clients echo checksums for verification</li></ol><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><ul><li><strong>No client-authoritative data:</strong> Score, position, inventory never trust client claims</li><li><strong>Deterministic sim + checksums:</strong> Server detects divergence immediately</li><li><strong>Replay safety:</strong> Monotonic seq + ack ensures no input is executed twice</li><li><strong>ML as advisory:</strong> Model flags suspicious patterns → reviewed before action (never auto-ban)</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Clients must implement backpressure when out-of-sequence</li><li>Input replay history stored per session (memory cost)</li><li>Server load increases with player count (all validation on one machine ⏳ horizontal scaling Phase 2)</li></ul><h2 id="implemented-in-code" tabindex="-1">Implemented In Code <a class="header-anchor" href="#implemented-in-code" aria-label="Permalink to &quot;Implemented In Code&quot;">​</a></h2><p><strong>✅</strong> Auth/authz validation: <code>backend/src/auth/mod.rs</code>, <code>backend/src/authz/mod.rs</code> (14 tests)</p><p><strong>✅</strong> Input frame seq validation: <code>backend/src/transport/protocol.rs::InputFrame</code> with seq field</p><p><strong>⏳</strong> Bounds checking per input type: <code>backend/src/game/mod.rs::execute_input()</code> — pending D4</p><p><strong>⏳</strong> ML advisory + review: <code>backend/src/admin/mod.rs::review_incident()</code> — pending D5</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>D1: Auth/authz modules wired into handshake</li><li>D4: Server authority validation tests</li><li>D5: Anti-cheat audit trail (no auto-ban)</li></ul>',19)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
